block.arguments:
{"command":"cd logs; 
gzip -dc checkout.log.2.gz > /tmp/ck0.log; cat /tmp/ck0.log checkout.log.1 checkout.log > /tmp/ck_all.log; wc -l /tmp/ck_all.log
echo "=== checkout error types with reqs"; grep ' ERROR ' /tmp/ck_all.log | grep -c '^'; 
awk '/ ERROR /{ for(i=1;i<=NF;i++) if($i ~ /^req=/) r=substr($i,5); if ($0 ~ /db pool exhausted/) print r, "POOL"; else if ($0 ~ /inventory call timed out/) print r, "INV" }' /tmp/ck_all.log > /tmp/ck_err.txt
wc -l /tmp/ck_err.txt; sort -k2 /tmp/ck_err.txt | cut -d' ' -f2 | uniq -c","description":"Build combined checkout log and error index"}

